import React, { useState } from "react";
import { login, uploadFile, analyzeText, analyzeStored } from "./api";

function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [token, setToken] = useState(null);
  const [file, setFile] = useState(null);
  const [storedFilename, setStoredFilename] = useState(null);
  const [text, setText] = useState("");
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  async function handleLogin(e) {
    e.preventDefault();
    setError(null);
    try {
      const res = await login(email, password);
      setToken(res.data.access_token);
    } catch (err) {
      setError(err?.response?.data?.detail || "Login failed");
    }
  }

  async function handleUpload(e) {
    e.preventDefault();
    if (!file) return setError("Select a file first");
    setLoading(true);
    try {
      const res = await uploadFile(file, token);
      setStoredFilename(res.data.stored_filename);
    } catch (err) {
      setError(err?.response?.data?.detail || "Upload failed");
    } finally {
      setLoading(false);
    }
  }

  async function handleAnalyzeText(e) {
    e.preventDefault();
    if (!text) return setError("Enter text to analyze");
    setLoading(true);
    try {
      const res = await analyzeText(text, token);
      setResults(res.data);
    } catch (err) {
      setError(err?.response?.data?.detail || "Analyze failed");
    } finally {
      setLoading(false);
    }
  }

  async function handleAnalyzeStored(e) {
    e.preventDefault();
    if (!storedFilename) return setError("No uploaded file stored");
    setLoading(true);
    try {
      const res = await analyzeStored(storedFilename, token);
      setResults(res.data);
    } catch (err) {
      setError(err?.response?.data?.detail || "Analyze failed");
    } finally {
      setLoading(false);
    }
  }

  if (!token) {
    return (
      <div style={{ padding: 20, maxWidth: 600, margin: "auto" }}>
        <h2>Legal AI Analyzer — Login (Single User)</h2>
        <form onSubmit={handleLogin}>
          <div>
            <label>Email</label><br />
            <input value={email} onChange={(e) => setEmail(e.target.value)} />
          </div>
          <div>
            <label>Password</label><br />
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
          </div>
          <button type="submit">Login</button>
          {error && <p style={{ color: "red" }}>{error}</p>}
        </form>
      </div>
    );
  }

  return (
    <div style={{ padding: 20, maxWidth: 900, margin: "auto" }}>
      <h2>Legal AI Document Analyzer</h2>
      <p>Logged in as single user. Upload PDF/DOCX or paste text to analyze.</p>

      <section style={{ marginBottom: 20 }}>
        <h3>Upload document</h3>
        <input type="file" onChange={(e) => setFile(e.target.files[0])} />
        <button onClick={handleUpload} disabled={loading || !file}>Upload & Encrypt</button>
        {storedFilename && <div>Stored as: <code>{storedFilename}</code></div>}
      </section>

      <section style={{ marginBottom: 20 }}>
        <h3>Analyze uploaded file</h3>
        <button onClick={handleAnalyzeStored} disabled={loading || !storedFilename}>Analyze Uploaded File</button>
      </section>

      <section style={{ marginBottom: 20 }}>
        <h3>Analyze pasted text</h3>
        <textarea value={text} onChange={(e) => setText(e.target.value)} rows={8} style={{ width: "100%" }} />
        <div>
          <button onClick={handleAnalyzeText} disabled={loading || !text}>Analyze Text</button>
        </div>
      </section>

      {loading && <p>Working…</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      {results && (
        <section>
          <h3>Results (showing up to {results.count})</h3>
          {results.clauses.map((c, i) => (
            <div key={i} style={{
              border: "1px solid #ddd",
              padding: 12,
              marginBottom: 10,
              borderRadius: 6,
            }}>
              <div style={{ fontWeight: "600" }}>Clause #{i+1} — Risk: <span style={{ color: c.risk === "High" ? "red" : c.risk === "Medium" ? "orange" : "green" }}>{c.risk}</span></div>
              <div style={{ marginTop: 8 }}>
                <strong>Original (truncated):</strong>
                <pre style={{ whiteSpace: "pre-wrap" }}>{c.clause}</pre>
              </div>
              <div><strong>Summary:</strong> {c.summary}</div>
              <div><strong>Labels:</strong> <pre style={{ whiteSpace: "pre-wrap" }}>{JSON.stringify(c.label, null, 2)}</pre></div>
            </div>
          ))}
        </section>
      )}
    </div>
  );
}

export default App;
